CREATE TABLE raw_ingest (
    ingested_at timestamptz NOT NULL,
    source text NOT NULL,
    payload jsonb NOT NULL
);

CREATE INDEX idx_raw_ingest_source ON raw_ingest(source);
CREATE INDEX idx_raw_ingest_ingested_at ON raw_ingest(ingested_at);

CREATE TABLE tag_map (
    tag_id text PRIMARY KEY,
    machine_id text NOT NULL,
    signal text NOT NULL,
    unit text NOT NULL,
    register text NOT NULL,
    scale double precision NOT NULL
);

CREATE INDEX idx_tag_map_machine_id ON tag_map(machine_id);
CREATE INDEX idx_tag_map_tag_id ON tag_map(tag_id);

CREATE TABLE machines (
    id text PRIMARY KEY,
    name text NOT NULL
);

CREATE TABLE buffers (
    id text PRIMARY KEY,
    capacity int NOT NULL,
    before text NOT NULL,
    after text NOT NULL
);

CREATE TABLE stations (
    id text PRIMARY KEY,
    processing_time_s double precision NOT NULL,
    availability_pct double precision NOT NULL,
    mttr_s double precision NOT NULL,
    power_working_kw double precision NOT NULL,
    power_idle_kw double precision NOT NULL
);

CREATE TABLE events (
    ts timestamptz NOT NULL,
    machine_id text NOT NULL,
    reason_code text NOT NULL,
    duration_s double precision NOT NULL,
    energy_kwh double precision NOT NULL
);

CREATE TABLE samples (
    ts timestamptz NOT NULL,
    machine_id text NOT NULL,
    tag text NOT NULL,
    value double precision NOT NULL
);

CREATE INDEX idx_events_machine_id ON events(machine_id);
CREATE INDEX idx_events_ts ON events(ts);
CREATE INDEX idx_samples_machine_id ON samples(machine_id);
CREATE INDEX idx_samples_tag ON samples(tag);

